export const meta = {
  name: 'auditoria-lcv557-lcv574',
  description: 'Auditoria diária consolidada LCV-557+LCV-574: inventário da frota, varredura por domínio e verificação adversarial dos achados',
  phases: [
    { title: 'Inventário', detail: 'frota viva, visibilidade, heads de main' },
    { title: 'Varredura', detail: 'um agente por domínio de auditoria' },
    { title: 'Verificação', detail: 'refutação adversarial dos achados >= LOW' },
  ],
}

const A = args
const COMMON = `
Contexto da auditoria (LCV Ideas & Software), modo APLICAR, RUN_KEY ${A.runKey}.
Janela de avaliação: ${A.windowStartBRT} a ${A.windowEndBRT} BRT (UTC ${A.windowStartUTC} a ${A.windowEndUTC}). Agora: ${A.nowBRT} BRT. Remediação não é limitada pela janela.
Regras duras para você (subagente):
- SOMENTE LEITURA, salvo quando o seu domínio disser explicitamente o contrário. Nunca execute git commit/push, nunca crie/edite PR, nunca comente em PR, nunca aprove nada. Mutações GitHub ficam com o orquestrador.
- Prefira as ferramentas MCP do GitHub (carregue via ToolSearch, ex.: "select:mcp__github__list_pull_requests") e do Linear (mcp__claude_ai_Linear__*). Para endpoints REST/GraphQL que o MCP não cobre, use o terminal persistente op run: python C:/Users/lcvle/lcv-workspace/github-operations/tools/op-terminal/opx.py --terminal default --shell pwsh --timeout <s> -f <script.ps1>  (escreva scripts em C:/Users/lcvle/lcv-workspace/github-operations/temp/lcv-574/<seu-dominio>/). O terminal é uma FILA SERIAL compartilhada: nada de laços de espera/sleep, timeout <= 300 s por chamada (exceto o domínio de licenciamento), agrupe muitas chamadas num único script. Nunca rode gh/curl autenticado fora do opx. Nunca imprima segredos.
- Paginação terminal obrigatória (hasNextPage/Link). Ausência só com paginação completa provada. Nada inventado: cada afirmação com identidade imutável (SHA completo, node ID, run ID, UUID) e a fonte.
- Cota esgotada sozinha não é achado.
- Repositório especial: .github (pasta local .github-org) e .github-private são bibliotecas de governança com exceções autorizadas (site/, package.json, quality/code-quality-probe.js, testes de paridade) — não são achados.
- Severidades: CRITICAL, HIGH, MEDIUM, LOW, OBSERVABILITY. Achado precisa de causa exata e evidência primária.
Frota viva (descoberta nesta execução): ${'${FLEET}'}
`

const FINDINGS = {
  type: 'object',
  properties: {
    domain: { type: 'string' },
    compliant: { type: 'array', items: { type: 'string' }, description: 'itens verificados conformes, com evidência concreta (SHA/ID)' },
    findings: { type: 'array', items: { type: 'object', properties: {
      id: { type: 'string' }, severity: { type: 'string' }, repo: { type: 'string' }, title: { type: 'string' },
      evidence: { type: 'string' }, cause: { type: 'string' }, remediation: { type: 'string' },
      mutation_needed: { type: 'string', description: 'mutação exata que o orquestrador deve executar (comando/arquivo/branch), ou vazio' },
    }, required: ['id', 'severity', 'repo', 'title', 'evidence', 'cause', 'remediation', 'mutation_needed'] } },
    writes_done: { type: 'array', items: { type: 'string' }, description: 'escritas efetivamente feitas por você (só domínios autorizados), com pre/post-read' },
    coverage_gaps: { type: 'array', items: { type: 'string' } },
  },
  required: ['domain', 'compliant', 'findings', 'writes_done', 'coverage_gaps'],
}

phase('Inventário')
const inv = await agent(`${COMMON.replace('${FLEET}', '(você vai descobrir)')}
Tarefa: descubra a frota viva. Via GraphQL no opx (organization(login:"LCV-Ideas-Software"){repositories(first:100, after:$cursor){pageInfo{hasNextPage endCursor} nodes{name isArchived visibility defaultBranchRef{name target{oid}} }}} paginando até o fim) mais o repositório pessoal lcv-leo/lcv-leo. Exclua arquivados. Retorne lista com nome completo owner/repo, visibilidade, branch padrão e SHA do head. Também leia o estado vivo do Enterprise ruleset 20582436 (só nome/enforcement) se acessível.`,
  { label: 'inventario-frota', schema: { type: 'object', properties: {
    repos: { type: 'array', items: { type: 'object', properties: { full: { type: 'string' }, visibility: { type: 'string' }, branch: { type: 'string' }, head: { type: 'string' } }, required: ['full', 'visibility', 'branch', 'head'] } },
    counts: { type: 'string' }, notes: { type: 'string' } }, required: ['repos', 'counts', 'notes'] } })

const FLEET = JSON.stringify(inv.repos)
const C = COMMON.replace('${FLEET}', FLEET)
log(`Frota: ${inv.counts}`)

const DOMAINS = [
  { key: 'dependabot', p: `PRIORIDADE MÁXIMA — o operador relatou "grande quantidade de PRs de Dependabot emperrados com problemas". Liste TODOS os PRs abertos de autor dependabot[bot] em toda a frota. Para cada um: número, título, idade, head SHA, mergeStateStatus, mergeable, auto-merge habilitado?, checks obrigatórios no head SHA exato (nome, conclusão, run ID), e para os BLOCKED a rule suite do ruleset (GET /repos/{o}/{r}/rulesets/rule-suites?ref=... ou rule-suites/{id}) com a regra que falha e a mensagem literal. Veja também conflitos (needs rebase), checks falhando com o log da etapa que falhou (job ID + linhas exatas do erro), e o workflow dependabot-auto-merge.yml do repo (run mais recente para o PR). AGRUPE por assinatura de causa (ex.: "Waiting for secret scan", "check X falha por Y", "conflito", "auto-merge não armado", "CodeQL esperando"). Para cada grupo proponha a remediação nativa exata: correção no main quando um workflow compartilhado está quebrado, "@dependabot rebase"/"@dependabot recreate" (comentário de comando do Dependabot é mecanismo nativo do próprio Dependabot — indique quando aplicável, mas NÃO poste), ou rerun de job falhado. Não revise nem comente PRs do Dependabot. Leia também os alertas Dependabot abertos de cada repo e se os PRs de segurança correspondem.` },
  { key: 'actions-saude', p: `Saúde do GitHub Actions na janela, em cada repo: runs failure/cancelled/timed_out/startup_failure/action_required e runs presos (queued/in_progress há mais de 1 h), com workflow, run ID, evento, head SHA, job/etapa que falhou e linha literal do erro (logs só dos falhados). Crons: para cada workflow com schedule, confirme que rodou na janela conforme o cron. Para cada commit em main dentro da janela: assinatura verificada (verification.verified + reason) e presença da linha de trailer Entire-Checkpoint na mensagem (exceto commits do Dependabot/GitHub). Exclua PRs do Dependabot do diagnóstico de causa (outro agente cuida), mas reporte runs de main quebrados por eles.` },
  { key: 'actions-pins', p: `Para cada repo, leia todos os arquivos .github/workflows/*.yml e .github/actions/**/action.yml no head de main e extraia cada "uses:" externo (owner/repo@ref). Para cada action única: release estável mais recente oficial (GET /repos/{o}/{r}/releases/latest e a tag correspondente -> SHA do commit, desreferenciando tags anotadas), compare com o SHA pinado e o comentário de versão. Liste desatualizados por repo (arquivo:linha, SHA atual, versão atual, SHA novo, versão nova) e indique se já existe PR aberto do Dependabot (github-actions) cobrindo aquele bump. Também sinalize pins que não são SHA completo de 40 caracteres ou que estejam sem comentário de versão.` },
  { key: 'wrangler', p: `Encontre em cada repo todo package.json (raiz e subpastas/workspaces) que declara wrangler (dependencies/devDependencies). Para cada um: versão declarada, versão resolvida no lockfile correspondente, e a versão atual no registro npm (registry.npmjs.org/wrangler -> dist-tags.latest, via opx com Invoke-RestMethod). Liste desatualizados com caminho exato. Verifique também o último deploy pós-merge (workflow de deploy) e se o log contém a versão do wrangler usada.` },
  { key: 'seguranca', p: `Segurança em cada repo conforme a visibilidade: alertas abertos de Code Scanning (ferramenta, regra, severidade, número), Secret Scanning (abertos, sem expor o segredo), Dependabot alerts (abertos, pacote, GHSA, manifest). CodeQL: análise mais recente em main (SHA e data). Zizmor e OpenSSF Scorecard: workflow presente, último run em main e conclusão. Rulesets efetivos em main (GET /repos/{o}/{r}/rules/branches/main): assinatura obrigatória, linear history, required status checks, conversation resolution, bloqueio de force-push/delete. Discussions: habilitado e 6 categorias de fábrica (exceto .github-private, que deve estar desabilitado).` },
  { key: 'licenciamento', p: `Licenciamento open source nativo (API version header X-GitHub-Api-Version: 2026-03-10). Para cada repo: leia a política Enterprise default e prove a regra license_compliance_scanning efetiva; peça o SBOM pela exportação assíncrona nativa (siga o contrato oficial; se só existir o endpoint síncrono /dependency-graph/sbom, use-o e registre isso), registre head SHA e SHA-256 dos bytes. Extraia os PURLs e envie em lotes de no máximo 40 para POST /repos/{o}/{r}/license-compliance/package-checks; para falha causada apenas pelo qualifier repository_url, repita uma vez sem ele e guarde as duas respostas. Agregue por repo: total de PURLs, allowed, denied, unknown/NOASSERTION. Política vigente: todas as licenças permitidas; denied é achado; unknown é limite de observação. Você pode usar timeout de até 1800 s no opx, num único script que faça tudo e grave o resumo em C:/Users/lcvle/lcv-workspace/github-operations/temp/lcv-574/licenciamento/; não faça laços de espera longos.` },
  { key: 'linear-github', p: `Mecanismos nativos GitHub<->Linear: instalações do GitHub App do Linear (repos com acesso), hooks da organização (GET /orgs/LCV-Ideas-Software/hooks; esperados Slack 661005468 e Linear 666684694: content_type json, insecure_ssl 0, eventos; o de commits só push) e as deliveries da janela (contagem, status != 2xx com ID). Para cada PR mesclado ou aberto na janela (exceto Dependabot) em toda a frota: verifique vínculo com Issue Linear (attachment no Linear apontando para a URL do PR, via mcp__claude_ai_Linear__get_issue do identificador citado no título/corpo/branch) e participação no Project GitHub individual do repo (1:1). Projects: Project #17 deve continuar inexistente; Project #15 deve ter exatamente 44 cartões cross-repo históricos (reporte só excesso). Para cada Issue aberta da organização, leia o campo nativo de organização Priority (node IFSS_kgDOAn85Eg) — reporte apenas inconsistências reais. Nenhuma escrita: proponha as arestas faltantes com prova de ausência terminal.` },
  { key: 'linear-higiene', p: `Higiene do Linear no Team LCV (10865b2d-83b3-481a-8b62-707a1e84ecaf) e demais teams. ESCRITA AUTORIZADA SÓ PARA PREENCHER CAMPO VAZIO em Issue aberta (Priority, Label, Project, Cycle quando em A Fazer/Em Andamento/Em Revisão), com leitura imediatamente antes e depois, e atribuição ao operador ("me") quando vazio; nunca sobrescreva campo preenchido divergente (vire achado), nunca toque em fechadas/canceladas/duplicadas, nunca escreva em LCV-557/LCV-574. Verifique: issues em Bloqueado/Triage/Backlog COM cycle (achado, não remova sem decisão), issues em voo sem cycle/priority/label/project. Inventário de ciclos (total, herdados vs graváveis pelo Team LCV, descrições <= 255). Asks/intake: liste as intake addresses ativas e destino (team ou template; templateData.teamId) — se a API do MCP não expuser, registre como superfície não observável com o erro literal. Caso específico: LCV-542 tem comentário-relatório dizendo estado final "Descartado" mas o estado vivo é "Em Andamento" — leia o histórico de estados (stateHistory) e diga quem/quando mudou e se é divergência real.` },
  { key: 'entire', p: `Entire: (1) recheque o critério pendente da LCV-542: no terminal opx rode "entire api /api/v1/..." conforme "entire agent-help api" para verificar se o checkpoint 01M6GNESZQJCE131SRMJRBR8VH agora é encontrado e se o commit 304166f31102c5dd787b06393e1052ea0f51d4a0 de LCV-Ideas-Software/maestro-app lista esse checkpoint (o suporte da Entire prometeu correção para 05/11/2026; issue entireio/cli#2980 — leia o estado e comentários novos dela via MCP GitHub). (2) Para cada repo, liste em main os commits da janela e quais têm trailer Entire-Checkpoint; para os que têm, confirme via git ls-remote no opx que refs/entire/checkpoints contém o ID. (3) Liste trails/findings abertos se "entire trail" estiver disponível (use entire agent-help trail). Somente leitura; não rode attach/resync.` },
  { key: 'slack', p: `Caminho GitHub->Slack: hook da organização do Slack (661005468): config, eventos, deliveries recentes na janela (status). Correlacione pelo menos uma delivery da janela com uma mensagem real em #github-activity ou #github-alerts (use mcp__claude_ai_Slack__slack_search_channels e slack_read_channel). Leia também #linear-activity e localize a mensagem consolidada anterior ID 1793703552.211299 (apenas leitura). Nenhuma postagem.` },
]

phase('Varredura')
const results = await pipeline(DOMAINS,
  d => agent(`${C}\nDomínio: ${d.key}\n${d.p}\nRetorne o objeto estruturado com domain="${d.key}".`, { label: `dom:${d.key}`, phase: 'Varredura', schema: FINDINGS }),
  (r, d) => {
    if (!r) return null
    const real = r.findings.filter(f => f.severity !== 'OBSERVABILITY')
    if (!real.length) return { ...r, verified: r.findings.map(f => ({ ...f, verdict: 'not-verified-observability' })) }
    return agent(`${C}\nVocê é o verificador adversarial do domínio ${d.key}. Para CADA achado abaixo, tente REFUTÁ-LO relendo o estado vivo agora (SHA/ID exatos): o achado é real, introduzido/visível no estado atual, com causa correta? Se já foi resolvido desde a varredura, diga "resolvido" com a prova. Seja cético.\nAchados:\n${JSON.stringify(real, null, 1)}`,
      { label: `verify:${d.key}`, phase: 'Verificação', schema: { type: 'object', properties: { verdicts: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, verdict: { type: 'string', enum: ['confirmado', 'refutado', 'resolvido', 'parcial'] }, proof: { type: 'string' }, corrected_cause: { type: 'string' } }, required: ['id', 'verdict', 'proof', 'corrected_cause'] } } }, required: ['verdicts'] } })
      .then(v => ({ ...r, verdicts: v ? v.verdicts : null }))
  })

return { inventory: inv, domains: results }

