cd C:/Users/lcvle/lcv-workspace && python -I - <<'EOF'
from pathlib import Path
import subprocess
WS=Path(r"C:\Users\lcvle\lcv-workspace"); master=(WS/"CLAUDE.md").read_bytes().decode()
BLOCK="<!-- entire-agent:begin -->"; RUN="## Running in GitHub Actions"
def rt(repo,f):
    r=subprocess.run(["git","-C",str(WS/repo),"show",f"origin/main:{f}"],capture_output=True)
    return r.stdout.decode() if r.returncode==0 else None
def head_before_block(t):
    out=[]
    for line in t.split("\n"):
        if line.strip()==BLOCK: return "\n".join(out).rstrip()
        out.append(line)
    return None
repos=[p.name.replace("-lcv577","") for p in (WS/".worktrees").glob("*-lcv577")]
for wt in sorted((WS/".worktrees").glob("*-lcv577")):
    name=wt.name[:-7]; repo=name if (WS/name).exists() else "."+name
    a=rt(repo,"AGENTS.md"); c=rt(repo,"CLAUDE.md"); parts=[]
    if a is not None:
        h=head_before_block(a)
        if h: parts.append(h)
    if c is not None and RUN in c:
        seg=RUN+c.split(RUN,1)[1]
        lines=[]
        for l in seg.split("\n"):
            if l.strip()==BLOCK: break
            lines.append(l)
        parts.append("\n".join(lines).rstrip())
    sec="\n\n".join(parts)
    exp=master.rstrip("\n")+"\n"+("\n---\n\n"+sec+"\n" if sec else "")
