    if (-not $tag) { $latest[$a] = @{ tag = 'SEM-RELEASE'; sha = '' }; continue }
    $ref = gh api "repos/$a/git/ref/tags/$tag" | ConvertFrom-Json
    $sha = if ($ref.object.type -eq 'tag') { (gh api "repos/$a/git/tags/$($ref.object.sha)" | ConvertFrom-Json).object.sha } else { $ref.object.sha }
