$ErrorActionPreference = 'Stop'
$fixes = Get-Content 'C:\Users\lcvle\AppData\Local\Temp\claude\3b79970522b9c3a1\38292320-4a80-44e1-9210-08b184a9b92b\scratchpad\fixes.json' -Raw -Encoding utf8 | ConvertFrom-Json
$session = '38292320-4a80-44e1-9210-08b184a9b92b'
$branch = 'claude/lcv-574-audit-fixes'
$title = 'chore(audit): resolve LCV-574 audit drift and Entire trail findings'
$q = [string][char]96
$ulid = '^01[0-9A-HJKMNP-TV-Z]{24}$'

$out = foreach ($f in $fixes) {
    $dir = if ($f.repo -eq '.github') { 'github-org' } else { $f.repo.TrimStart('.') }
    $wt = "C:\Users\lcvle\lcv-workspace\.worktrees\$dir-lcv574"
    Push-Location $wt
    try {
        $slug = ((git remote get-url origin) -replace '^.*github\.com[:/]', '' -replace '\.git$', '')
        $untracked = @(git ls-files --others --exclude-standard)
        $unexpected = @($untracked | Where-Object { $_ -notin $f.changed_files })
        if ($unexpected.Count) { throw "arquivos não rastreados inesperados: $($unexpected -join ', ')" }
        git add -u
        if ($untracked.Count) { git add -- $untracked }
        $staged = @(git diff --cached --name-only)
        if ($staged | Where-Object { $_ -in 'AGENTS.md', 'CLAUDE.md' }) { throw 'AGENTS.md/CLAUDE.md no diff' }
        if (-not $staged.Count) { throw 'nada para commitar' }
        New-Item -ItemType Directory -Force temp | Out-Null
        $msg = "$title`n`n$($f.summary.Trim())`n`nRefs LCV-574`n`nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>`n"
        [IO.File]::WriteAllText("$wt\temp\msg.txt", $msg.Replace("`r`n", "`n"))
        git commit -q -S -F temp/msg.txt; if ($LASTEXITCODE) { throw 'commit' }
        entire session attach $session --agent claude-code --commit (git rev-parse HEAD) --force 2>&1 | Out-Null; if ($LASTEXITCODE) { throw 'attach' }
        git commit -q --amend --no-edit -S; if ($LASTEXITCODE) { throw 'resign' }
        git push -q -u origin $branch 2>&1 | Out-Null; if ($LASTEXITCODE) { throw 'push' }
        $fixedLines = @($f.findings_fixed | ForEach-Object { "- ${q}$($_.id)${q}: $($_.how)" })
        $dismissLines = @($f.findings_dismiss | Where-Object { $_.id -match $ulid } | ForEach-Object { "- ${q}$($_.id)${q}: $($_.reason)" })
        $gateLines = @($f.gates | ForEach-Object { "- ${q}$($_.cmd)${q}: $($_.result)" })
        $body = "## Summary`n`n$($f.summary.Trim())`n`n## Entire trail findings`n`n**Fixed**`n`n" +
            $(if ($fixedLines.Count) { $fixedLines -join "`n" } else { '- none' }) +
            "`n`n**Not changed in code (reason recorded on the trail)**`n`n" +
            $(if ($dismissLines.Count) { $dismissLines -join "`n" } else { '- none' }) +
            "`n`n## Local validation`n`n" + ($gateLines -join "`n") +
            "`n`nAGENTS.md and CLAUDE.md are not part of this change (operator decision LCV-577).`n`nRefs LCV-574`n`n🤖 Generated with [Claude Code](https://claude.com/claude-code)`n"
        [IO.File]::WriteAllText("$wt\temp\body.md", $body.Replace("`r`n", "`n"))
        $hasLabel = gh label list --repo $slug --search Claude --json name --jq '[.[] | select(.name=="Claude")] | length'
        $ghArgs = @('pr', 'create', '--repo', $slug, '--base', 'main', '--head', $branch, '--title', $title, '--body-file', "$wt\temp\body.md")
        if ($hasLabel -eq '1') { $ghArgs += @('--label', 'Claude') }
        $url = gh @ghArgs; if ($LASTEXITCODE) { throw 'pr create' }
        git commit -q --amend --no-edit -S; if ($LASTEXITCODE) { throw 'handshake amend' }
        git push -q --force-with-lease origin $branch 2>&1 | Out-Null; if ($LASTEXITCODE) { throw 'handshake push' }
        Remove-Item -Recurse -Force temp
        $cp = git log -1 --format='%(trailers:key=Entire-Checkpoint,valueonly,separator=)'
        '{0} {1} arquivos={2} sig={3} cp={4} cpRef={5} label={6}' -f $f.repo, $url, $staged.Count, (git log -1 --format=%G?), $cp, [bool](git ls-remote origin 'refs/entire/checkpoints/*' | Select-String -SimpleMatch $cp), $hasLabel
    } catch {
        "{0} ERRO: {1}" -f $f.repo, $_.Exception.Message
    } finally { Pop-Location }
}
$out
